  Ltac pxo PX := repeat (apply PIXat_out; [| rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; lia | rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn; lia]); exact PX.

  (* [comment removed for export] *)
  Lemma rb_N : forall regs m (s : Z) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
    rdn SEGS (FRBn m s ret regs) (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) ->
    rdn SEGS (FRBn m s ret regs) (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x940fc : word) m rom) (mkst regs' (0x6311c : word) (FRBn m s ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret
      /\ getr regs' 10 = Z_to_bv 64 0x10355 /\ getr regs' 11 = Z_to_bv 64 0x1636a /\ getr regs' 12 = Z_to_bv 64 0
      /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9 /\ getr regs' 18 = getr regs 18 /\ getr regs' 19 = getr regs 19
      /\ getr regs' 20 = getr regs 20 /\ getr regs' 21 = getr regs 21 /\ getr regs' 22 = getr regs 22 /\ getr regs' 23 = getr regs 23
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 18; 19; 20; 21; 22; 23]%list) regs regs'.
Proof.
