  (* [comment removed for export] *)
  Lemma cs_A : forall regs m (s pixs : Z) (v : pixv) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 80 \/ s <= pixs)%Z -> p_d v = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs ->
    getr regs 11 = Z_to_bv 64 1 -> getr regs 12 = Z_to_bv 64 1 -> getr regs 13 = Z_to_bv 64 0 -> getr regs 14 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x93e4c : word) m rom) (mkst regs' (0xfa23c : word) (FCS m s ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 1 = Z_to_bv 64 0x93ebc
      /\ getr regs' 10 = Z_to_bv 64 256 /\ getr regs' 11 = Z_to_bv 64 1
      /\ getr regs' 19 = Z_to_bv 64 pixs /\ getr regs' 21 = Z_to_bv 64 1 /\ getr regs' 20 = Z_to_bv 64 1
      /\ getr regs' 9 = Z_to_bv 64 0 /\ getr regs' 8 = Z_to_bv 64 0
