  Lemma cs_T0 : forall regs m (tab : Z), (0 <= tab)%Z -> (tab + 256 < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 tab ->
    exists regs',
      msteps SEGS (mkst regs (0x93ebc : word) m rom) (mkst regs' (0x93ed8 : word) m rom)
      /\ getr regs' 18 = Z_to_bv 64 tab /\ getr regs' 15 = Z_to_bv 64 tab /\ getr regs' 14 = Z_to_bv 64 (tab + 256)
      /\ regs_agree (fun r => In r [10; 11; 12; 13; 14; 15; 18]%list) regs regs'.
