  (* [comment removed for export] *)
  Lemma cs_T : forall regs m (p : Z), (0 <= p)%Z -> (p + 1 < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 p) 1 = true -> getr regs 15 = Z_to_bv 64 p ->
    exists regs' (b : byte),
      msteps SEGS (mkst regs (0x93ed8 : word) m rom) (mkst regs' (0x93f30 : word) (wbytes m (Z_to_bv 64 p) [b]) rom)
      /\ getr regs' 15 = Z_to_bv 64 (p + 1)
      /\ regs_agree (fun r => In r [5; 6; 7; 10; 11; 12; 13; 15; 16; 17; 28; 29]%list) regs regs'.
Proof.
